    function GetEyeName(OrganId) {
        if (OrganId === 1) {
            return "Right Eye";
        }
        if (OrganId === 2) {
            return "Left Eye";
        }
        if (OrganId === 3) {
            return "Both Eyes";
        }
        if (OrganId === 4) {
            return "General";
        }
        if (OrganId === 5) {
            return "Hair";
        }
        if (OrganId === 6) {
            return "Skin";
        }
        if (OrganId === 7) {
            return "Laser";
        }
    }

