        if ($scope.AppointInfo.AppointmentStatus == "E" || $scope.AppointInfo.AppointmentStatus == "D") {
            $scope.IsConsultationCompleted = true;
        }
      
        if ($scope.AppointInfo.AppointmentStatus == "E" && $scope.AppointInfo.DoctorID === $scope.UserId) {
            $scope.IsConsultationCompleted = false;
        }
