        $scope.parentProfileTab.MainTab = 5;
        $scope.screenComesToBilling = true;

        var param = {
            "AppoitmentDate": $filter('date')(new Date(), "yyyy-MM-dd"),
            "HospitalId": $scope.HospitalId,
            "DoctorId": 0,
            "GetAllDoctorIndictor": 1,
            "AppointmentTypeId": 0,
            "PatientId": 0,
            "PageSize": 50,
            "PageNo": 1
        };

        eHnoteMainAppointmentService.GetAllOPandOTAppointmentList(param).then(function (respose) {
            console.log(respose);
            if (respose.data.status == "Success") {
                if (respose.data.rows.length > 0) {
                    
                    $scope.AppointmentObj.CurrentDateAppointmentList = respose.data.rows || [];
                    angular.forEach($scope.AppointmentObj.CurrentDateAppointmentList, function (pitem) {
                        pitem.Patient.patientId = pitem.Patient.PatientId;
                        pitem.Patient.PatientID = pitem.Patient.PatientId;
                        pitem.PatientId = pitem.Patient.PatientId;
                    });

                } else {
                    //$scope.cacheStorageItem.CurrentDateAppointmentList = [];
                    $scope.AppointmentObj.CurrentDateAppointmentList = [];
                }
                eHnoteCacheStorageService.addCacheStorage($scope.cacheStorageItem);
            }

        }, function (error) {
            console.log(error);
        });
