        $scope.Headers = $scope.GetHeaderInfo();
        $scope.Headers.AddresHeader = true;
        $scope.PatientAddressInfo = angular.copy(AddressDetails);
        $scope.RegisterPatientSave();
        $scope.SaveTypeObj.TypeName = "AddressDetails";
