    $scope.searchCountyByZipCode = function (zipcode, GetMode) {
        eHnoteSettingsDataService.getCountiesByZipCode(zipcode).then(function (resp) {
            if (resp.data.Status === "Success") {
                $scope.countyCodesArray = resp.data.rows || [];

                if (GetMode === "GetCounty") {
                    if ($scope.PatientAddressSummary.PermanentAddress.CountyId != 0 && $scope.PatientAddressSummary.PermanentAddress.CountyId != null) {
                        $scope.PatientAddressSummary.PermanentAddress.CountyCodeObj = $filter("filter")($scope.countyCodesArray, { "CountyId": $scope.PatientAddressSummary.PermanentAddress.CountyId })[0] || "";
                    }
                }
            }
        });
    };
