    $scope.GetstateandZipcodeByParmanentCity = function (CityName, stateid) {
        eHnotePatientAddressDataServices.SearchCity(CityName).then(function (resp) {
            if (resp.data.length > 0) {
                var patientList = resp.data || [];
                var GetZipcodeList = [];
                stateid = stateid || 0;

                if (patientList.length > 0) {
                    $scope.PermanentStates = [];
                    angular.forEach(patientList, function (suitem) {
                        suitem.Name = suitem.StateName || "";
                        $scope.PermanentStates.push(suitem);
                        if (suitem.StateId === stateid) {
                            $scope.PatientAddressInfo.PermanentAddress.ZipCodeArray = angular.copy(suitem.ZipCodeArray) || [];
                        }
                        GetZipcodeList = GetZipcodeList.concat(suitem.ZipCodeArray);
                    });
                    if ($scope.PatientAddressInfo.PermanentAddress.ZipCodeArray.length === 0) {
                        if (GetZipcodeList.length > 0) {
                            $scope.PatientAddressInfo.PermanentAddress.ZipCodeArray = angular.copy(GetZipcodeList) || [];
                        } else {
                            $scope.PatientAddressInfo.PermanentAddress.ZipCodeArray = [];
                        }
                    }
                } else {
                    $scope.PermanentStates = angular.copy($scope.states) || [];
                }

            }
        });
    };
