    $scope.viewEditPopUp = function (type, item) {
        $scope.Showeditpatient = true;
        $scope.ShowInsuranceAddnew = true;
        $scope.Headers = $scope.GetHeaderInfo();
        if (type === 1) {
            $scope.PatientDetailsInfo = "";
            $scope.PatientDetailsInfo = angular.copy(item);
            $scope.Headers.PatientHeader = true;
            $scope.SaveTypeObj.TypeName = "PatientDetails";

            if ($scope.PatientDetailsInfo.PatientTagId != 0 && $scope.PatientDetailsInfo.PatientTagId != null) {
                $scope.PatientDetailsInfo.PatientTagObj = $filter("filter")($scope.HospitalEquipmentList, { "HospitalEquipmentId": $scope.PatientDetailsInfo.PatientTagId })[0] || "";
            }

            $scope.SelectedPatientTagList = [];
            $scope.SelectedPatientTagList = angular.copy($scope.HospitalEquipmentList);
            if ($scope.PatientDetailsInfo.PatientTagList.length > 0) {
                angular.forEach($scope.PatientDetailsInfo.PatientTagList, function (item) {
                    angular.forEach($scope.SelectedPatientTagList, function (kitem) {
                        if (item.HospitalEquipmentId == kitem.HospitalEquipmentId) {
                            kitem.IsChecked = true;
                        }
                    });
                });
            }

            $scope.ageinYears = $scope.PatientDetailsInfo.AgeInYears || "";
            $scope.ageinMonths = $scope.PatientDetailsInfo.AgeInMonths.toString() || "";
            $scope.ageinDays = $scope.PatientDetailsInfo.AgeInDays.toString() || "";

            var phoneNumberString = item.ContactInfo.HomeAreaCode + item.ContactInfo.HomeNumber;
            $scope.formatUSNumberInfo(phoneNumberString);

            var AlternateNumberString = item.ContactInfo.OfficeAreaCode + item.ContactInfo.OfficeNumber;
            $scope.formatUSNumberAlternateinfo(AlternateNumberString);

        }
        if (type === 2) {
            $scope.Headers.AddresHeader = true;
            $scope.PatientAddressInfo = angular.copy(item);
            if (!$scope.ValidateIndictor) {
                $scope.SaveTypeObj.TypeName = "AddressDetails";
                $scope.Headers = $scope.GetHeaderInfo();
                $scope.Headers.AddresHeader = true;
            }

            if ($scope.PatientAddressInfo.PermanentAddress.CityName != "") {
                $scope.GetstateandZipcodeByParmanentCity($scope.PatientAddressInfo.PermanentAddress.CityName, $scope.PatientAddressInfo.PermanentAddress.StateId);
            }
            if ($scope.PatientAddressInfo.PostalAddress.CityName != "") {
                $scope.GetstateandZipcodeByPostalCity($scope.PatientAddressInfo.PostalAddress.CityName, $scope.PatientAddressInfo.PostalAddress.StateId);
            }


            //$scope.PatientAddressInfo.IsCheckCopy = false;
            if ($scope.PatientAddressInfo.PostalAddress.AddressLine1 == '' && $scope.PatientAddressInfo.PostalAddress.AddressLine2 == '' && $scope.PatientAddressInfo.PostalAddress.ZipCode == '' && $scope.PatientAddressInfo.PostalAddress.CityName == '' && $scope.PatientAddressInfo.PostalAddress.CountryName == '' && $scope.PatientAddressInfo.PostalAddress.CountyName == '' && $scope.PatientAddressInfo.PostalAddress.StateName == '' &&
                $scope.PatientAddressInfo.PermanentAddress.AddressLine1 == '' && $scope.PatientAddressInfo.PermanentAddress.AddressLine2 == '' && $scope.PatientAddressInfo.PermanentAddress.ZipCode == '' && $scope.PatientAddressInfo.PermanentAddress.CityName == '' && $scope.PatientAddressInfo.PermanentAddress.CountryName == '' && $scope.PatientAddressInfo.PermanentAddress.CountyName == '' && $scope.PatientAddressInfo.PermanentAddress.StateName == '') {
                $scope.PatientAddressInfo.IsCheckCopy = false;
            }
            //else {
            //    $scope.PatientAddressInfo.IsCheckCopy = true;
            //}


        }
        if (type === 3) {
            $scope.Headers.DemographicsHeader = true;
            $scope.EditDemographicDetails(item, "JustTabMove");
        }
        if (type === 4) {
            $scope.Headers.FamilyMemberHeader = true;
            $scope.EditFamilyDetails(item, "JustTabMove");
        }
        if (type === 5) {

            $scope.Headers.DesignatedHeader = true;
            $scope.EditDesignatedDetails(item, "JustTabMove");
        }
        if (type === 6) {
            //  $scope.SubHeaders.PrimaryInsuranceHeader = true;
            $scope.Headers.InsuranceHeader = true;
            $scope.EditInsuranceDetails(item, "JustTabMove");

        }





    };


    $scope.searchReferalDoctors = function (val, typeid) {

        var searchtext = "", searchNPI = "";
        if (isNaN(val)) {
            searchtext = val;
        }
        else {
            searchNPI = val;
        }

        var param = {
            'LocationId': null,
            'PageNumber': 1,
            'PageSize': 20,
            'SearchTaxt': searchtext,
            "SpecializationId": null,
            "DeleteInd": 'N',
            "NPI": searchNPI,
            "RefaralTypeId": typeid,
            "OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID
        };
        return eHnoteReferalDataService.GetReferalPCPDoctors(param).then(function (resp) {
            if (resp.data.count !== 0) {
                if (resp.data.PcpRefdetails.length > 0) {
                    return resp.data.PcpRefdetails.map(function (item) {
                        return item;
                    });
                }
            }
        }, function (error) {
            console.log(error);
        });
    }

    $scope.changePCPRefereal = function (text) {
        $scope.filteredPCPArray = [];

        if (text === "") {
            $scope.filteredPCPArray = angular.copy($scope.ReferalPCPDoctorsList);
        }
        if (isNaN(text)) {
            $scope.filteredPCPArray = [];
            var patientfilter = $filter("filter")($scope.ReferalPCPDoctorsList, { "DoctorName": text }) || [];
            if (patientfilter.length > 0) {
                $scope.filteredPCPArray = patientfilter;
            }

        } else {
            $scope.filteredPCPArray = [];
            var patientfilter = $filter("filter")($scope.ReferalPCPDoctorsList, { "NPI": text }) || [];
            if (patientfilter.length > 0) {
                $scope.filteredPCPArray = patientfilter;
            }
        }
    };

