    $scope.GetUpcomingAppointments = function (patientId) {
        var appointmentinfo = eHnoteMasterDataService.getAppointmentInfo();
        if (appointmentinfo.PatientID == 0 || appointmentinfo.PatientID == null) {
            return false;
        }
        var PHospitID = null;
        var HospitID = null;
        if (doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo !== undefined && doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalCode !== undefined) {
            PHospitID = doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID;
            HospitID = doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID
        }
        eHnoteUserAppointmentDataService.GetPatientUpcomingAppointments(patientId, PHospitID).then(function (response) {
            console.log(response);
            $scope.AllAppointmentsArray = [];
            $scope.FutureAppointmentsArray = [];
            $scope.UpcomingAppointmentArray = [];
            $scope.IsCompleteandSend = false;
            if (response.data.Status == "Success") {
                if (response.data.AllAppointments.length > 0) {
                    $scope.AllAppointmentsArray = angular.copy(response.data.AllAppointments);
                    if ($scope.AllAppointmentsArray.length > 0) {
                        angular.forEach($scope.AllAppointmentsArray, function (item) {
                            item.ShowAppointmentNotes = false;
                            item.ShortStartTime = $filter('date')(new Date(item.AppointmentDate + " " + item.StartTime), "hh:mm a");
                        });
                    }
                }
                if (response.data.rows.length > 0) {

                    $scope.FutureAppointmentsArray = angular.copy(response.data.rows);
                    //  $scope.UpcomingAppointmentArray = angular.copy(response.data.rows);
                    angular.forEach(response.data.rows, function (item, index) {
                        // if (index == 0 || index == 1 || index == 2 || index == 3 || index == 4) {
                        item.IsVisitcardCheckBox = false;
                        $scope.UpcomingAppointmentArray.push(item);
                        //}
                    });
                    angular.forEach($scope.UpcomingAppointmentArray, function (item) {
                        let todaydate = $filter('date')(new Date(), "yyyy-MM-dd");
                        item.IsCompleteandsendInd = false;
                        item.IsCheckInInd = false;
                        item.IsOnlyComplete = true;
                        if (item.ConsultationDt > todaydate || item.ConsultationDt == todaydate) {
                            item.IsHideCheckin = true;
                        } else {
                            item.IsHideCheckin = false;

                        }
                        if (item.ConsultationDt == todaydate) {
                            item.IsOnlyComplete = false;
                            if ($scope.PreviousUrl === '/crm') {
                                item.IsOnlyComplete = true;
                            }
                        }


                        if (item.ConsultationDt > todaydate || item.ConsultationDt == todaydate) {
                            item.IsHideEditInd = true;
                        } else {
                            item.IsHideEditInd = false;
                        }

                        if (item.AppointmentStatus == 'R') {
                            item.IsHideEditInd = false;
                        }
                        if (item.AppointmentStatus == 'R') {
                            item.IsHideEditInd = false;
                        }
                        if (item.AppointmentStatus != 'C' && item.AppointmentStatus != 'R' && item.CheckinStatusId == 1 && (item.ConsultationDt > todaydate || item.ConsultationDt == todaydate)) {
                            item.IsCheckInInd = true;
                        }

                        if (item.AppointmentStatus != 'C' && item.AppointmentStatus != 'R' && item.CheckinStatusId == 2 && (item.ConsultationDt > todaydate || item.ConsultationDt == todaydate)) {
                            item.IsCompleteandsendInd = true;
                        }

                        if ($scope.PreviousUrl === '/crm') {
                            item.IsCompleteandsendInd = false;
                        }

                        if (!item.IsCompleteandsendInd) {
                            item.IsOnlyComplete = true;
                        }
                    });
                    if ($scope.AllAppointmentsArray.length > 0) {
                        angular.forEach($scope.AllAppointmentsArray, function (item) {
                            item.ShowAppointmentNotes = false;
                        });
                    }
                    if ($scope.FutureAppointmentsArray.length > 0) {
                        angular.forEach($scope.FutureAppointmentsArray, function (item) {
                            item.ShowAppointmentNotes = false;
                        });
                        $scope.SelectAppointment($scope.FutureAppointmentsArray[0]);
                    }



                    var tempAppointmentArray = [];
                    tempAppointmentArray = response.data.rows;
                    var Appt_doctorId = 0;
                    if (appointmentinfo.DoctorID == undefined) {
                        appointmentinfo.DoctorID = appointmentinfo.doctorID;
                    }
                    if (appointmentinfo.DoctorID != undefined) {
                        Appt_doctorId = angular.copy(appointmentinfo.DoctorID);
                    } else if (appointmentinfo.DoctorId != undefined) {
                        Appt_doctorId = angular.copy(appointmentinfo.DoctorId);
                    }
                    var todaydate = $filter("date")(new Date(), "yyyy-MM-dd");
                    // code for visit reason and checkin status binding in all role logins // by sumanth
                    let newfilterappointments = $filter("filter")(tempAppointmentArray, { "AppointmentDate": todaydate, "BranchId": HospitID }, true) || [];
                    newfilterappointments = newfilterappointments.filter((x) => x.AppointmentStatus !== "C");
                    if (newfilterappointments.length > 0) {
                        let appointmentinfonew = eHnoteMasterDataService.getAppointmentInfo();
                        appointmentinfonew.VisitTypeId = newfilterappointments[0].VisitTypeId || null;
                        appointmentinfonew.AppointmentTypeId = newfilterappointments[0].AppointmentTypeId || null;
                        appointmentinfonew.AppointmentID = newfilterappointments[0].AppointmentID || null;
                        appointmentinfonew.CheckinStatusId = newfilterappointments[0].CheckinStatusId || null; // after checkin refresh checkinstatusis
                        appointmentinfonew.VisitReason = newfilterappointments[0].VisitReason || null;
                        eHnoteMasterDataService.addAppointmentInfo(appointmentinfonew);
                    }



                    var filterappointments = $filter("filter")(tempAppointmentArray, { "AppointmentDate": todaydate, "BranchId": HospitID, "DoctorId": Appt_doctorId }, true) || [];  //, "DoctorId": doctorinfo.doctorid
                    filterappointments = filterappointments.filter((x) => x.AppointmentStatus !== "C");
                    if (filterappointments.length > 0) {
                        var data = filterappointments[0];
                        if (data.AppointmentStatus === "D" || data.AppointmentStatus === "E" || data.AppointmentStatus === "O") {
                            $scope.cacheStorageItem.TreatmentPlanId = data.TreatmentPlanId || 0;
                            $scope.cacheStorageItem.ConsultationID = data.ConsultationId || 0;
                            $scope.cacheStorageItem.appointmentid = data.AppointmentID || 0;
                            $scope.cacheStorageItem.AppointmentDt = data.ConsultationDt;
                            $scope.cacheStorageItem.IsFollowupConsultation = false;
                            //  $scope.cacheStorageItem.IsNewConsultation = false;
                            // $scope.cacheStorageItem.IsEditConsultation = true;
                            $scope.cacheStorageItem.IsfindingsDataInitialized = false;
                            $scope.cacheStorageItem.AppointmentDoctorID = data.DoctorId || 0;
                            $scope.cacheStorageItem.appointmentStatus = data.AppointmentStatus;
                            $scope.cacheStorageItem.VisitRemarks = data.VisitRemarks;
                            $scope.cacheStorageItem.ProfileStatusMasterId = data.ProfileStatusMasterId;
                            $scope.cacheStorageItem.VisitReason = data.VisitReason;

                        } else if (data.AppointmentStatus === "B") {
                            $scope.cacheStorageItem.appointmentid = data.AppointmentID;
                            $scope.cacheStorageItem.AppointmentDt = data.ConsultationDt;
                            $scope.cacheStorageItem.TreatmentPlanId = 0;
                            $scope.cacheStorageItem.ConsultationID = 0;
                            // $scope.cacheStorageItem.IsNewConsultation = true;
                            $scope.cacheStorageItem.IsEditConsultation = false;
                            $scope.cacheStorageItem.IsFollowupConsultation = false;
                            $scope.cacheStorageItem.IsfindingsDataInitialized = false;
                            $scope.cacheStorageItem.AppointmentDoctorID = data.DoctorId;
                            $scope.cacheStorageItem.ConsultationDate = $scope.cacheStorageItem.AppointmentDt;
                            $scope.cacheStorageItem.appointmentStatus = data.AppointmentStatus;
                            $scope.cacheStorageItem.VisitRemarks = data.VisitRemarks;
                            $scope.cacheStorageItem.ProfileStatusMasterId = data.ProfileStatusMasterId;
                            $scope.cacheStorageItem.VisitReason = data.VisitReason;
                        }
                        eHnoteCacheStorageService.addCacheStorage($scope.cacheStorageItem);

                        var tempappointmentinfo = eHnoteMasterDataService.getAppointmentInfo();
                        tempappointmentinfo.AppointmentStatus = data.AppointmentStatus || "";
                        tempappointmentinfo.AppointmentID = data.AppointmentID || 0;
                        tempappointmentinfo.AppointmentId = data.AppointmentID || 0;
                        tempappointmentinfo.DoctorID = data.DoctorId || 0;
                        tempappointmentinfo.DoctorFullName = data.DoctorName || "";
                        tempappointmentinfo.HospitalId = data.BranchId || null;
                        tempappointmentinfo.TreatmentPlanId = data.TreatmentPlanId || 0;
                        tempappointmentinfo.BranchId = data.BranchId || 0;
                        tempappointmentinfo.BranchName = data.BranchName || "";
                        tempappointmentinfo.ConsultationDt = data.ConsultationDt || "";
                        tempappointmentinfo.ConsultationId = data.ConsultationId || 0;
                        tempappointmentinfo.StartTime = data.StartTime || "";
                        tempappointmentinfo.EndTime = data.EndTime || "";
                        tempappointmentinfo.BillingId = data.BillingId || 0;
                        tempappointmentinfo.PatientInsuranceList = data.PatientInsuranceList || [];
                        tempappointmentinfo.AppointmentTOSCodes = data.AppointmentTOSCodes || [];
                        tempappointmentinfo.CheckinStatusId = data.CheckinStatusId;
                        tempappointmentinfo.PaymentTypeId = data.PaymentTypeId || 2;
                        tempappointmentinfo.VisitRemarks = data.VisitRemarks || "";
                        tempappointmentinfo.VisitTypeId = data.VisitTypeId || null;
                        tempappointmentinfo.ProfileStatusMasterId = data.ProfileStatusMasterId || "";
                        tempappointmentinfo.VisitReason = tempappointmentinfo.VisitReason || "";

                        eHnoteMasterDataService.addAppointmentInfo(tempappointmentinfo);

                        appointmentinfo = eHnoteMasterDataService.getAppointmentInfo();

                        if (userLoginDetails.RoleID === 1 || userLoginDetails.RoleID === 3 || userLoginDetails.RoleID === 4 || userLoginDetails.RoleID === 43 ||
                            userLoginDetails.RoleID === 16 || userLoginDetails.RoleID === 56 || userLoginDetails.RoleID === 57 || userLoginDetails.RoleID === 10) {
                            if ($scope.cacheStorageItem.appointmentid == 0) {
                                $scope.IsConsultationCompleted = true;
                            } else {
                                $scope.IsConsultationCompleted = false;
                            }
                        } else {
                            //$scope.IsConsultationCompleted = true;
                            $scope.IsConsultationCompleted = false;  // alert changes
                        }

                        $scope.IsCompleteandSend = true;
                    }
                    else {
                        // $scope.IsConsultationCompleted = true;
                        $scope.IsConsultationCompleted = false;  // alert changes
                        var tempappointmentinfo = eHnoteMasterDataService.getAppointmentInfo();
                        tempappointmentinfo.AppointmentID = tempappointmentinfo.AppointmentID || 0;
                        tempappointmentinfo.AppointmentId = tempappointmentinfo.AppointmentId || 0;
                        tempappointmentinfo.VisitTypeId = tempappointmentinfo.VisitTypeId || 0;
                        tempappointmentinfo.CheckinStatusId = tempappointmentinfo.CheckinStatusId || 0;
                        tempappointmentinfo.AppointmentTypeId = tempappointmentinfo.AppointmentTypeId || 0;
                        tempappointmentinfo.VisitReason = tempappointmentinfo.VisitReason || "";
                        tempappointmentinfo.PaymentTypeId = 2;


                        eHnoteMasterDataService.addAppointmentInfo(tempappointmentinfo);
                    }
                } else {
                    $scope.UpcomingAppointmentArray = [];
                    $scope.cacheStorageItem.appointmentid = $scope.cacheStorageItem.appointmentid || 0;
                    $scope.cacheStorageItem.appointmentStatus = $scope.cacheStorageItem.appointmentStatus || "";
                    if ($scope.cacheStorageItem.appointmentid == 0) {
                        //  $scope.IsConsultationCompleted = true;
                        $scope.IsConsultationCompleted = false;   // alert changes
                    } else {
                        $scope.IsConsultationCompleted = false;

                        if (appointmentinfo.AppointmentStatus == "C") {
                            $scope.IsConsultationCompleted = true;
                        }
                    }
                    var tempappointmentinfo = eHnoteMasterDataService.getAppointmentInfo();
                    tempappointmentinfo.AppointmentID = 0;
                    tempappointmentinfo.AppointmentId = 0;
                    tempappointmentinfo.CheckinStatusId = 0;
                    tempappointmentinfo.PaymentTypeId = 2;

                    eHnoteMasterDataService.addAppointmentInfo(tempappointmentinfo);

                }

                $scope.ModifySelectedAppointment();
                $scope.ProfileObj.IsShowProfileScreen = true;
            } else {
                $scope.IsConsultationCompleted = true;
                alertify.error(Message);
            }
        }, function (error) {
            console.log(error);
        });
    };



