    $scope.PatientPCPDocuments = [];
    $scope.selectPCPimagelist = function ($files) {
        $scope.PatientDesignatedInfo.PatientPCPDocuments = $scope.PatientDesignatedInfo.PatientPCPDocuments || [];
        $scope.PatientDesignatedInfo.S3URL = '';
        $scope.file = "";

        $scope.file = $files;

        if ($scope.file != null) {
            if ($scope.file.length > 0) {
                angular.forEach($scope.file, function (fitem) {
                    var pName = fitem.name, name = "";
                    var type = fitem.type.split("/")[1];
                    if (pName.length > 9) {
                        name = pName.substring(0, 9) + "..." + "." + type;
                    } else {
                        name = angular.copy(pName) + '.' + type;
                    }
                    var SelectedDate = $filter("date")(new Date(), "yyyy-MM-dd");
                    var obj = {
                        "file": fitem,
                        "DeleteInd": "N",
                        "PatientPCPDocumentId": 0,
                        "DocumentExt": fitem.type,
                        "DocumentName": name,
                        "S3URL": "",
                        "FileTypeId": 10,
                        "SignedDate": SelectedDate,
                        "DisplayName": name || "",
                        "Remarks": "",
                    };



                    if (fitem.type != 'application/pdf') {
                        $scope.PatientDesignatedInfo.PatientPCPDocuments.push(obj);
                    }
                    else {
                        $scope.PatientDesignatedInfo.PatientPCPDocuments.push(obj);
                    }


                });
            }
        }
    };
