    $scope.RemoveReferralImage = function (item, index) {

        if (item.PatientPCPDocumentId != 0) {
            var r = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>Are you sure want to delete? </h4>",

                function () {
                    if ($scope.PatientDesignatedInfo.PatientPCPDocuments.length > 0) {

                        // angular.forEach($scope.PatientDesignatedInfo.PatientPCPDocuments, function (Doc) {

                        $scope.DocumentPcp =
                        {
                            "UserId": $scope.UserId,
                            "HospitalID": $scope.HospitalId,
                            "PatientDesignatedDocumentDetail": [{
                                "DocumentId": item.PatientPCPDocumentId,
                                "DocumentTypeId": 4,
                                "DocumentName": item.DocumentName,
                                "DocumentExt": item.DocumentExt,
                                "S3URL": item.S3URL,
                                "DeleteInd": "Y"
                            }]

                        }
                        //   if (item.PatientPCPDocumentId == Doc.PatientPCPDocumentId) {

                        eHnotePatientDataService.DeleteDesignatedDocumentDetailsById($scope.DocumentPcp).then(function (resp) {
                            console.log(resp);
                            if (resp.data.status == "Success") {


                                // $scope.PatientDesignatedInfo.PatientPCPDocuments.splice(index, 1);
                                var filterTinsSummary = $filter("filter")($scope.PatientDesignatedSummary.SummaryPcpDocument, { "PatientPCPDocumentId": item.PatientPCPDocumentId }, true) || [];
                                if (filterTinsSummary.length > 0) {
                                    var indexSummary = $scope.PatientDesignatedSummary.SummaryPcpDocument.indexOf(filterTinsSummary[0]);
                                    $scope.PatientDesignatedSummary.SummaryPcpDocument.splice(indexSummary, 1);
                                }
                                var filterDesignated = $filter("filter")($scope.PatientDesignatedInfo.PatientPCPDocuments, { "PatientPCPDocumentId": item.PatientPCPDocumentId }, true) || [];
                                if (filterDesignated.length > 0) {
                                    var IndexPatientInfo = $scope.PatientDesignatedInfo.PatientPCPDocuments.indexOf(filterDesignated[0]);
                                    $scope.PatientDesignatedInfo.PatientPCPDocuments.splice(IndexPatientInfo, 1);
                                }
                                var filterTins = $filter("filter")($scope.PatientDesignatedSummary.PatientPCPDocuments, { "PatientPCPDocumentId": item.PatientPCPDocumentId }, true) || [];
                                if (filterTins.length > 0) {
                                    var index = $scope.PatientDesignatedSummary.PatientPCPDocuments.indexOf(filterTins[0]);
                                    $scope.PatientDesignatedSummary.PatientPCPDocuments.splice(index, 1);
                                }
                            }
                            alertify.success("Deleted Successfully");

                        }, function (err) {
                            console.log(err);
                            alertify.error("Deleting Failed");
                        });


                    }

                })
        }
        else {
            $scope.PatientDesignatedInfo.PatientPCPDocuments.splice(index, 1);
        }
    }

