    $scope.ClearAlldesignatedinfobyAppointment = function (SelectedAppointmentObj) {
        var remove = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>Are you sure want to clear designated info? </h4>", function () {
            var referralid = $scope.PatientApptPCPInfo.PatientDesignatedInfoId || 0;
            var referraldocument = angular.copy($scope.PatientApptPCPInfo.PatientPCPDocuments);
            $scope.PatientApptPCPInfo = GetApptPCPInfo();
            $scope.PatientApptPCPInfo.PatientDesignatedInfoId = referralid;
            $scope.PatientApptPCPInfo.PatientPCPDocuments = angular.copy(referraldocument);
            if ($scope.PatientApptPCPInfo.PatientPCPDocuments.length > 0) {
                angular.forEach($scope.PatientApptPCPInfo.PatientPCPDocuments, function (pitem) {
                    pitem.DeleteInd = "Y";
                });
            }

            var TempDesignated = angular.copy($scope.PatientApptPCPInfo);
            TempDesignated.PatientID = $scope.patientid;
            TempDesignated.FullName = $scope.PatientName;
            TempDesignated.ReferralName = "";
            TempDesignated.MasterReferralSourceId = 0;
            TempDesignated.ReferralSourceId = 0;
            $scope.PatientApptPCPInfo.ReferralDate = null;

            eHnotePatientDataService.AddUpdateAppointmentDesignatedDetailsnew(TempDesignated, OnAddPatientSuccess, OnAddPatientError);
            function OnAddPatientSuccess(resp) {
                if (resp.Status === "Success") {
                    $scope.SelectAppointment(SelectedAppointmentObj);
                    alertify.success("Referral Info Deleted Successfully");
                }
            }
            function OnAddPatientError() {
                alertify.error("Creating  Failed");
            }

        }, function () {
            remove = "You pressed Cancel!";
        });
    }


