    $scope.ClearAllAuthorizationsbyAppointment = function (SelectedAppointmentObj) {
        var remove = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>Are you sure want to clear designated info? </h4>", function () {

            var PreAuthId = $scope.summaryAppointmentPreAuthDataObj.PatientPreAuthorizationId || 0;
            var PreAuthdocument = angular.copy($scope.summaryAppointmentPreAuthDataObj.PatientPreAuthDocuments);

            $scope.summaryAppointmentPreAuthDataObj = getSummaryAppointmentPreAuthDataObj();
            $scope.summaryAppointmentPreAuthDataObj.PatientPreAuthorizationId = PreAuthId;
            $scope.summaryAppointmentPreAuthDataObj.PatientPreAuthDocuments = PreAuthdocument || [];

            $scope.summaryAppointmentPreAuthDataObj.UserId = $scope.UserId,
                $scope.summaryAppointmentPreAuthDataObj.BranchId = $scope.HospitalId
            $scope.summaryAppointmentPreAuthDataObj.PatientId = SelectedAppointmentObj.PatientId;
            $scope.summaryAppointmentPreAuthDataObj.AppointmentId = SelectedAppointmentObj.AppointmentID;
            $scope.summaryAppointmentPreAuthDataObj.PatientName = $scope.PatientName;
            // $scope.summaryAppointmentPreAuthDataObj.ServiceDate = null;
            //$scope.summaryAppointmentPreAuthDataObj.ExpiryDate = null;

            if ($scope.summaryAppointmentPreAuthDataObj.PatientPreAuthDocuments.length > 0) {
                angular.forEach($scope.summaryAppointmentPreAuthDataObj.PatientPreAuthDocuments, function (pitem) {
                    pitem.DeleteInd = "Y";
                });
            }

            var TempDesignated = $scope.summaryAppointmentPreAuthDataObj;
            eHnotePatientDataService.AddUpdateAppointmentPreAuthorizationData(TempDesignated, OnAddPatientSuccess, OnAddPatientError);
            function OnAddPatientSuccess(resp) {
                console.log(resp);
                if (resp.status === "Success") {
                    let req = { "AppointmentId": SelectedAppointmentObj.AppointmentID, "PatientId": SelectedAppointmentObj.PatientId }
                    $scope.GetSummaryAppointmentPreAuthData(req);
                }
            }
            function OnAddPatientError() {
                alertify.error("Creating  Failed");
            }

        }, function () {
            remove = "You pressed Cancel!";
        });
    }


