    $scope.PatientDemographicPrint = function () {

        let InsurenceItemPrint = [];
        angular.forEach($scope.PatientApptInsuInfo, function (item) {
            let PrintPatientInsuranceDetailId = $filter("filter")($scope.PatientInsuranceSummary, function (fitem) {
                return fitem.PatientInsuranceDetailId === item.PatientInsuranceDetailId;
            });
            if (PrintPatientInsuranceDetailId.length > 0) {
                InsurenceItemPrint.push(PrintPatientInsuranceDetailId[0]);
            }

        });
        var Obj = {
            "PatientBaseInfo": angular.copy($scope.PatientDetailSummary),
            "Addressinfo": $scope.PatientAddressSummary,
            "DesignationInfo": $scope.PatientApptPCPInfo || "",
            "Demographicinfo": $scope.DemographicSummary || "",
            "insuranceinfo": angular.copy(InsurenceItemPrint) || [],
            "PatientImg": $scope.PatientProfileImageBase64 || "",
            "PatientNotes": angular.copy($scope.RegisterPatientNotesArray) || []
        };
        Obj.PatientBaseInfo.PatientMobileNumber = $scope.PatientMobileNumber || "";
        Obj.PatientBaseInfo.PatientOfficeNumber = $scope.PatientOfficeNumber || "";
        Obj.PatientBaseInfo.EmailID = Obj.PatientBaseInfo.ContactInfo.EmailID || "";
        if (Obj.insuranceinfo.length > 0) {
            angular.forEach(Obj.insuranceinfo, function (item) {
                item.EligibilityStatusName = "";
                item.frontbase64 = "";
                var filter = $filter("filter")($scope.InsuranceStatusList1, { "StatusId": item.EligibilityStatusId }) || [];
                if (filter.length > 0) {
                    item.EligibilityStatusName = filter[0].StatusName;
                }

                if (item.PatientDocumentDetails.length > 0) {
                    angular.forEach(item.PatientDocumentDetails, function (subitem) {
                        if (subitem.IsBackSidefile == false) {
                            var filter1 = $filter("filter")($scope.PatientInsurancebase64, { "Documentid": subitem.DocumentId }) || [];
                            if (filter1.length > 0) {
                                item.frontbase64 = filter1[0].frontbase64;
                            }
                        }
                    });
                }
            });
        }
        //console.log(JSON.stringify(Obj));
        //console.log(Obj.PatientImg);
        USPrintService.generatePatientDemograpicPrint(Obj);
    }
    $scope.PatientProfileImageBase64 = "";
    $scope.toDataURL = function (dataURL, callback) {
        var xhr = new XMLHttpRequest();
        xhr.onload = function () {
            var reader = new FileReader();
            reader.onloadend = function () {
                callback(reader.result);
            };
            reader.readAsDataURL(xhr.response);
        };
        xhr.open('GET', dataURL);
        xhr.responseType = 'blob';
        xhr.send();
    };

    //visitcardpritn
    $scope.VisitCardApptobj = {
        "IsEnableCheckbox": false
    }
    $scope.ChangeVisitCardApptcheck = function () {
        angular.forEach($scope.UpcomingAppointmentArray, function (item) {
            item.IsVisitcardCheckBox = false;
        });
    }

    $scope.VisitCardprint = function () {

        if ($scope.VisitCardApptobj.IsEnableCheckbox == true) {
            var count = 0;
            angular.forEach($scope.UpcomingAppointmentArray, function (item) {
                if (item.IsVisitcardCheckBox == true) {
                    count++;
                }
            });
            if (count == 0) {
                alertify.error("Please Select An Up-coming Appointment");
                return;
            }
        }

        if ($scope.UpcomingAppointmentArray.length == 0) {
            alertify.error("There is no Upcoming Appointments");
            return;
        }


        var obj = {
            "patientinfo": angular.copy($scope.PatientDetailSummary),
            "UpcomingAppointment": []
        };
        //$scope.UpcomingAppointmentArray
        var today = $filter("date")(new Date(), "yyyy-MM-dd");
        if ($scope.UpcomingAppointmentArray.length > 0) {
            if ($scope.VisitCardApptobj.IsEnableCheckbox == false) {
                var filter = $filter("filter")($scope.UpcomingAppointmentArray, function (iterator, ind) { return iterator.ConsultationDt !== today; }) || [];
                if (filter.length > 0) {
                    obj.UpcomingAppointment = angular.copy(filter);
                    angular.forEach(obj.UpcomingAppointment, function (item) {
                        item.shortdate = $filter('date')(new Date(item.ConsultationDt + " " + "00:00:00"), "MM-dd-yyyy");
                        item.shorttime = $filter('date')(new Date(item.ConsultationDt + " " + item.StartTime), "hh:mm a");
                    });
                }
            } else {
                var filter = $filter("filter")($scope.UpcomingAppointmentArray, function (iterator, ind) { return iterator.IsVisitcardCheckBox == true; }) || [];
                if (filter.length > 0) {
                    obj.UpcomingAppointment = angular.copy(filter);
                    angular.forEach(obj.UpcomingAppointment, function (item) {
                        item.shortdate = $filter('date')(new Date(item.ConsultationDt + " " + "00:00:00"), "MM-dd-yyyy");
                        item.shorttime = $filter('date')(new Date(item.ConsultationDt + " " + item.StartTime), "hh:mm a");
                    });
                }
            }
        }

        USPrintService.generateVisitCardPrint(obj);

        angular.forEach($scope.UpcomingAppointmentArray, function (item) {
            item.IsVisitcardCheckBox = false;
        });
        $scope.VisitCardApptobj.IsEnableCheckbox = false;
    }

