    $scope.ClickRemindersPopup = function (RemainderItem) {
        $scope.mInstanceAdd = $uibModal.open({
            "templateUrl": "templates/uibpopups/SetReminderPopover.html",
            "backdrop": "static",
            "scope": $scope,
            "keyboard": false,
            "size": "md",
            /*"windowClass": "modal-full",*/
            "resolve": {
                "UserId": function () { return $scope.UserId; },
                "HospitalId": function () { return $scope.HospitalId; },
                "appointmentid": function () { return $scope.cacheStorageItem.appointmentid; },
                "PatientID": function () { return $scope.cacheStorageItem.PatientID || $scope.cacheStorageItem.patientid || 0; },
                "RemainderItem": function () { return RemainderItem; },
            },
            "controller": function ($scope, $uibModal, $uibModalInstance, UserId, HospitalId, appointmentid, PatientID, RemainderItem) {

                $scope.UserId = UserId || 0;
                $scope.HospitalId = HospitalId || 0;
                $scope.appointmentid = appointmentid || 0;
                $scope.PatientID = PatientID || 0;

                function getnewReminderObj() {
                    var obj = {
                        "PatientReminderId": 0,
                        "ReminderDate": "",
                        "Type": "Date",
                        "DurationType": "",
                        "Duration": "",
                        "ReminderRemarks": ""
                    };
                    return obj;
                }
                $scope.ReminderObj = getnewReminderObj();

                if (RemainderItem !== undefined) {

                    if (RemainderItem.Date == null) {
                        var RemDate = $filter("date")(RemainderItem.Duration, "yyyy-MM-dd") || '';
                    } else {
                        var RemDate = $filter("date")(RemainderItem.Date, "yyyy-MM-dd") || '';
                    }

                    /*$scope.ReminderObj.ReminderDate = RemDate || '';*/
                    $scope.ReminderObj.ReminderDate = $filter("date")(RemDate, "MM-dd-yyyy");
                    $scope.ReminderObj.Type = 'Date';
                    $scope.ReminderObj.ReminderRemarks = RemainderItem.Remarks || '';

                }

                $scope.navtoClearReminderObj = function () {
                    $uibModalInstance.dismiss("cancel");
                }

                $scope.navtoSaveReminder = function () {

                    var SelectedDate = $filter("date")($scope.ReminderObj.ReminderDate, "yyyy-MM-dd") || null;
                    var SelectedDurationToDate = $filter("date")($scope.ReminderObj.DurationDate, "yyyy-MM-dd") || null;


                    if ($scope.ReminderObj.ReminderDate == "" && $scope.ReminderObj.DurationDate == undefined) {
                        alertify.error("Please Select Reminder Date or Duration ");
                        return;
                    }


                    var obj = {

                        "UserId": $scope.UserId,
                        "PatientAppointmentReminderId": 0,
                        "HospitalId": $scope.HospitalId,
                        "PatientId": $scope.PatientID || 0,
                        "AppointmentId": $scope.appointmentid || 0,
                        "Type": $scope.ReminderObj.Type,
                        "Date": SelectedDate || SelectedDurationToDate || null,
                        "DurationType": $scope.ReminderObj.DurationType,
                        //"Duration": SelectedDurationToDate || null,
                        "Duration": null,
                        "Remarks": $scope.ReminderObj.ReminderRemarks,
                        "DeleteInd": "N"

                    }
                    if (RemainderItem !== undefined) {
                        obj.PatientAppointmentReminderId = RemainderItem.PatientAppointmentReminderId || 0;
                    }
                    eHnoteMainAppointmentService.AddSetRemainderDetails(obj).then(function (resp) {
                        console.log(resp);
                        if (resp.data.status == "Success") {
                            alertify.success("Reminder Added Successfully");
                            $scope.GetSetReminderId();
                            $scope.ReminderObj = getnewReminderObj();
                            /*$uibModalInstance.dismiss("cancel");*/
                        }
                    }, function (err) {
                        alertify.error("Getting Failed");
                    });
                }

                $scope.GetSetReminderId = function () {

                    var param = {
                        /*"AppointmentId": $scope.appointmentid || 0,*/
                        "AppointmentId": 0,
                        "PatientId": $scope.PatientID || 0,
                    }

                    eHnoteMainAppointmentService.GetSetReminderDetails(param).then(function (resp) {
                        if (resp.data.status == "Success") {
                            $scope.SetReminderArray = resp.data.rows;
                            $scope.mInstanceAdd.close($scope.SetReminderArray);
                        }
                    }, function (err) {
                        alertify.error("Getting Failed");
                    });
                }

                $scope.ChangeDurationstep = function () {
                    $scope.BindfollowUpData($scope.ReminderObj.DurationType, 'click');
                }

                $scope.BindfollowUpData = function (val, type) {
                    var TodayDate = $filter('date')(new Date(), "yyyy-MM-dd");
                    var FollowUpDuration = parseFloat($scope.ReminderObj.Duration) || 0;
                    $scope.cacheStorageItem.FollowUpDurationType = val;
                    $scope.cacheStorageItem.FollowUpDurationTypeName = val === "Y" ? "Year(s)" : (val === "C" ? "To Be continued" : (val === "M" ? "Month(s)" : (val === "D" ? "Day(s)" : (val === "W" ? "Week(s)" : (val === "L" ? "Life Time" : "")))));
                    var TempFollowUpObj = eHnotePatientDataService.GetFollowUpDate(FollowUpDuration, $scope.cacheStorageItem.FollowUpDurationType, new Date(TodayDate));
                    /*$scope.ReminderObj.DurationDate = TempFollowUpObj.FollowUpDate;*/
                    $scope.ReminderObj.DurationDate = $filter('date')(new Date(TempFollowUpObj.FollowUpDate), "yyyy-MM-dd");
                };
                $scope.changeReminderType = function () {
                    $scope.ReminderObj.DurationType = 'D';
                    $scope.ReminderObj.Duration = '';
                    $scope.ReminderObj.ReminderRemarks = '';
                    $scope.ReminderObj.ReminderRemarks = '';
                    $scope.ReminderObj.ReminderDate = '';
                }
            }
        });
        $scope.mInstanceAdd.result.then(function (resp) {
            $scope.SetReminderArray = resp || [];
        }, function () { });
    };

    $scope.DeleteAppointmentInsurance = function (obj, SelectedAppointmentObj) {
        obj = obj || "";
        if (obj != "") {
            let reqObj = {
                "UserId": $scope.UserId,
                "AppointmentInsuranceDetailId": obj.PatientAppointmentInsuranceDetailId || null,
                "AppointmentId": $scope.SelectedAppointmentObj.AppointmentID || null,
                "DeleteInd": "Y",
                "PaymentTypeId": 1
            };
            eHnoteUserAppointmentDataService.DeleteAppointmentInsurance(reqObj).then(function (resp) {
                if (resp.data.Status === "Success") {
                    alertify.success("Insurance is deleted successfully");
                    //$scope.SelectedAppointmentObj = "";
                    if ($scope.parentProfileTab.UpComingApptTab === 2) {
                        $scope.GetOldandNewAllAppointments($scope.patientid);
                    } else {
                        $scope.GetUpcomingAppointments($scope.patientid);
                    }
                }
            });
        }
    };

    $scope.ApptInsuranceObj = {
        "PrimaryInsurance": "",
        "SecondaryInsurance": "",
        "OtherInsurance": ""
    };

    $scope.changePatientInsurance = function (obj, parentobj, str) {
        obj = obj || "";
        if (parentobj.PatientInsuranceList.length > 0) {
            let count = 0;
            angular.forEach(parentobj.PatientInsuranceList, function (item) {
                if (item.PatientInsuranceDetailId == obj.PatientInsuranceDetailId) {
                    count++;
                }
            });
            if (count > 0) {
                alertify.error("Selected Insurance is already added!");
                if (str == "Primary") {
                    $scope.ApptInsuranceObj.PrimaryInsurance = "";
                } else if (str == "Secondary") {
                    $scope.ApptInsuranceObj.SecondaryInsurance = "";
                } else {
                    $scope.ApptInsuranceObj.OtherInsurance = "";
                }
            }
        }

    };

    $scope.AddInsurancetoAppt = function (obj, val) {

        $scope.SelectedAppointmentObj.PatientInsuranceList = $scope.SelectedAppointmentObj.PatientInsuranceList || [];
        if ($scope.SelectedAppointmentObj.PatientInsuranceList.length > 3 || $scope.SelectedAppointmentObj.PatientInsuranceList.length == 3) {
            alertify.error("Max limit reached for insurance");
            return false;
        }

        if (val === 1) {
            if ($scope.ApptInsuranceObj.PrimaryInsurance == "") {
                alertify.error("Please select primary insurance!");
                return;
            }
        }
        if (val === 2) {
            if ($scope.ApptInsuranceObj.SecondaryInsurance == "") {
                alertify.error("Please select secondary insurance!");
                return;
            }
        }
        if (val === 5) {
            if ($scope.ApptInsuranceObj.OtherInsurance == "") {
                alertify.error("Please select insurance!");
                return;
            }
        }
        let IdentifierId;
        if (val === 1) {
            IdentifierId = 1;
        } else if (val === 2) {
            IdentifierId = 2;
        } else {
            IdentifierId = 5;
        }

        let reqObj = {
            "UserId": $scope.UserId,
            "ParentHospitalId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID || null,
            "AppointmentInsuranceDetailId": 0,
            "AppointmentId": $scope.SelectedAppointmentObj.AppointmentID || null,
            "PatientId": $scope.patientid,
            "InsuranceDetaildId": obj.PatientInsuranceDetailId || null,
            "IdentifierId": IdentifierId,
            "StatusId": obj.StatusId || 0,
            "EligibilityStatusId": obj.EligibilityStatusId || 0,
            "PaymentTypeId": 2
        };
        //console.log(JSON.stringify(reqObj));

        eHnoteUserAppointmentDataService.AddInsuranceToAppointment(reqObj).then(function (resp) {
            if (resp.data.status === "Success") {
                alertify.success("Insurance added Successfully");

                if ($scope.parentProfileTab.UpComingApptTab === 2) {
                    $scope.GetOldandNewAllAppointments($scope.patientid);
                } else {
                    $scope.GetUpcomingAppointments($scope.patientid);
                }
                if (val === 1) {
                    $scope.ApptInsuranceObj.PrimaryInsurance = "";
                } else {
                    $scope.ApptInsuranceObj.SecondaryInsurance = "";
                }
            }
        });

    };

    $scope.DeleteRemainder = function (Data) {
        var obj = {

            "UserId": Data.DoctorID,
            "PatientAppointmentReminderId": Data.PatientAppointmentReminderId || 0,
            "HospitalId": Data.HospitalId,
            "PatientId": Data.PatientId || 0,
            "AppointmentId": Data.AppointmentId || 0,
            "Type": Data.Type,
            "Date": Data.Date || "",
            "DurationType": Data.DurationType,
            "Duration": Data.Duration || "",
            "Remarks": Data.Remarks,
            "DeleteInd": "Y"

        }
        eHnoteMainAppointmentService.AddSetRemainderDetails(obj).then(function (resp) {
            console.log(resp);
            if (resp.data.status == "Success") {
                alertify.success("Remainder Deleted Successfully");
                $scope.GetSetReminderId($scope.UpcomingAppointmentArray);
            }
        }, function (err) {
            alertify.error("Getting Failed");
        });
    };

    $scope.DesignatedSummaryObj = {
        "Tab": 1
    };

    $scope.SelectTabInDesignated = function (val) {
        $scope.DesignatedSummaryObj.Tab = val;
    };


    if ($scope.PreviousUrl === '/op') {
        if ($scope.RoleId === 1 || $scope.RoleId === 16 || $scope.RoleId === 4 || $scope.RoleId === 43 || $scope.RoleId === 62 || $scope.RoleId === 63 || $scope.RoleId === 66 || $scope.RoleId === 67 || $scope.RoleId === 68 || $scope.RoleId === 69 || $scope.RoleId === 55 || $scope.RoleId === 25 || $scope.RoleId === 18 || $scope.RoleId === 10 || $scope.RoleId === 11 || $scope.RoleId === 5) {
            $scope.parentProfileTab.PatientAndApptTab = 2;
            $scope.parentProfileTab.UpComingApptTab = 1;
            $scope.GetUpcomingAppointments($scope.patientid);
            $scope.getPatientInsuranceDetailsOfPatient();
        }
    };
    $scope.othernotes = {
        "Notes": "",
        "CreatedDt": "",
        "CreatedBy": "",
        "NotesTab": 1
    }
    $scope.Notestabchange = function (Type) {
        $scope.othernotes.NotesTab = Type || 1;
    }
    $scope.getApptAdditionalDetails1 = function (id) {
        id = id || null;
        eHnoteMainAppointmentService.getAdditionalApptDetailsById(id).then(function (resp) {

            resp.data = resp.data || [];

            if (resp.data.length > 0) {
                $scope.AppointmentNotesArray = resp.data[0].AppointmentNotes;

                if (resp.data[0].AppointmentDetails.length > 0) {
                    var obj = resp.data[0].AppointmentDetails[0];

                    if (obj.RescheduledAppointmentId !== 0) {
                        $scope.SelectedAppointmentObj.RescheduledAppointmentId = obj.RescheduledAppointmentId;
                        $scope.SelectedAppointmentObj.RescheduledAppointmentDate = obj.RescheduledAppointmentDate;
                        $scope.SelectedAppointmentObj.RescheduledAppointmentStartTime = obj.RescheduledAppointmentStartTime;
                        $scope.SelectedAppointmentObj.RescheduledAppointmentEndTime = obj.RescheduledAppointmentEndTime;
                        $scope.SelectedAppointmentObj.RescheduledDoctorId = obj.RescheduledDoctorId;

                        var starray = $scope.SelectedAppointmentObj.RescheduledAppointmentStartTime.split(":");
                        var st1 = starray[0];
                        var st2 = starray[1];

                        console.log(st1, st2);

                        var stime = getdtTimes(st1, st2);

                        $scope.SelectedAppointmentObj.RescheduledAppointmentStartTime = stime;
                    }
                    $scope.othernotes.Notes = obj.OtherNotes || "";
                    $scope.othernotes.CreatedDt = obj.ModifiedDt || "";
                    $scope.othernotes.CreatedBy = obj.ModifiedBy || "";

                }

            } else {
                $scope.AppointmentNotesArray = [];
            }
        }, function (err) {
            console.log(err);
            alertify.error("Getting data failed");
        });
    };

    function getdtTimes(hours, mins) {
        var h = hours, m = mins;
        var thistime = (h > 12) ? (h - 12 + ':' + m + ' PM') : (h + ':' + m + ' AM');
        console.log(thistime);
        return thistime;
    }

    $scope.IsShowEligibiltySave = false;
    $scope.onEligibilityChange = function () {
        $scope.IsShowEligibiltySave = true;
    };

